using System;using System.Linq;using System.Drawing;using System.Reflection;using System.Windows.Forms;using System.Collections.Generic;
class CastAnimationChecks {
 static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static object Get(Game g,string n){return typeof(Game).GetField(n,F).GetValue(g);}static object Call(Game g,string n,params object[] a){return typeof(Game).GetMethod(n,F).Invoke(g,a);}static void Check(bool b,string n){if(!b)throw new Exception(n);}static void Pump(int ms){var w=System.Diagnostics.Stopwatch.StartNew();while(w.ElapsedMilliseconds<ms){Application.DoEvents();System.Threading.Thread.Sleep(8);}}
 static void Shot(Control c,string name){using(var b=new Bitmap(c.Width,c.Height)){c.DrawToBitmap(b,c.ClientRectangle);b.Save("D:/WORK/Cet6Story/.validation/"+name+".png");}}
 [STAThread]static void Main(){try{Application.EnableVisualStyles();using(var g=new Game()){g.Opacity=0;g.Show();Pump(100);var save=new Save();typeof(Game).GetField("save",F).SetValue(g,save);save.toxicWoodland=ToxicWoodland.Create(0,save);var r=save.toxicWoodland;r.current=r.nodes.First(n=>n.kind=="battle").id;r.steps=2;r.mode="node-combat";Call(g,"ShowToxicWoodland");Call(g,"StopAudio");var run=r.combat;var b=run.partyBattle;var canvas=(PartyBattleCanvas)Get(g,"partyCanvas");Check(canvas.MaleActions!=null&&canvas.FemaleActions!=null,"action art loaded");var hero=b.heroes[b.selectedHero];Check(PartyCombat.BeginSkill(b,b.selectedHero,"bolt",b.enemies[0].id),"begin bolt");Call(g,"NextPartyQuestion",run);Call(g,"RenderPartyBattle",run);Call(g,"AnswerPartyQuestion",run.question.answer);Check(canvas.IsCasting&&canvas.Controls.OfType<BattleGlassPanel>().All(p=>!p.Visible),"casting visible without result obstruction");int cursor=b.cursor;Call(g,"ContinuePartyBattle");Check(b.cursor==cursor,"cannot skip while casting");var timer=(Timer)typeof(PartyBattleCanvas).GetField("castTimer",F).GetValue(canvas);timer.Stop();System.Threading.Thread.Sleep(980);Shot(canvas,"casting-luchuan-attack-game");timer.Start();Check(Object.ReferenceEquals(canvas,Get(g,"partyCanvas")),"stable canvas");Pump(1250);Check(!canvas.IsCasting&&canvas.Controls.OfType<BattleGlassPanel>().Any(p=>p.Visible),"result returns after animation");
 foreach(var pair in new[]{new[]{"aelia","slash","enemy-0"},new[]{"aelia","guard","luchuan"},new[]{"luchuan","inscribe","enemy-0"},new[]{"luchuan","screen","aelia"}}){foreach(var p in canvas.Controls.OfType<BattleGlassPanel>())p.Visible=false;int hp=b.enemies[0].hp;canvas.PlayCast(pair[0],pair[1],pair[2],true,null);timer.Stop();System.Threading.Thread.Sleep(980);Shot(canvas,"casting-"+pair[0]+"-"+pair[1]+"-game");timer.Start();Pump(1250);Check(!canvas.IsCasting&&hp==b.enemies[0].hp,"visual animation does not apply damage twice");}g.Close();Console.WriteLine("PASS game casting: both atlases, attack/chant/shield frames, long-range effect layer, result delayed, stable canvas, skip guard, no duplicate damage");}}catch(Exception e){while(e!=null){Console.WriteLine(e.GetType().Name+": "+e.Message);e=e.InnerException;}Environment.ExitCode=1;}}
}
